    (* [comment removed for export] *)
    Lemma apath_at_A : forall M R,
      frame_mod mem0 M regA_w -> regs_ok E0 srA R -> (length path <= 4095)%nat ->
      path_at_lazy asegs R M path.
Proof.
      (* LPS 727298f3 port: written out (rule 11g).  [path_at_lazy] carries a third conjunct,
         the string's end below TASK_SIZE; it follows from [astr_at]'s bound on the string. *)
      intros M R FM HR Hlen.
      destruct (aopenat_regs R HR) as (_ & _ & R11 & _).
      pose proof Hpp as [_ HA]. unfold astr_at in HA. destruct HA as (Sge & Sfit & Snul & Srd & _).
      pose proof (bv_unsigned_in_range 64 sp0) as Hsp. unfold bv_modulus in Hsp.
      assert (Upp : bv_unsigned (Z_to_bv 64 pp) = pp).
      { rewrite Z_to_bv_unsigned, bv_wrap_small; [reflexivity|]. change (bv_modulus 64) with (2^64)%Z. lia. }
      unfold path_at_lazy. rewrite R11.
      split; [exact Hlen|]. split; [exact Snul|]. split.
      - rewrite Upp. unfold TASK_SIZE. lia.
      - transitivity (rdn asegs mem0 (Z_to_bv 64 pp) (length path + 1)); [|exact Srd].
        apply OSSVerify.Proofs.boost_json.fuzz_parse.lib.PropExec.rdn_ext; [rewrite Upp; lia|].
        intros x [Hx1 _]. apply (above_A M FM). rewrite Upp in Hx1. lia.
    Qed.

