      regs_ok E0 srA R -> know_ok RSEGS E0 M knA ->
      (forall R' msF' mo',
          as_VIS H s0 msF' = mkst R' (Z_to_bv 64 0x90b5c) M rom -> as_AKREL H s0 (mkCfg msF' mo') -> same_but_materialized mo mo' ->
          getr R' 1 = Z_to_bv 64 0xbe974 -> getr R' 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) ->
          getr R' 4 = Z_to_bv 64 0x6f43d8 -> getr R' 8 = Z_to_bv 64 2 -> getr R' 10 = Z_to_bv 64 0x10000 ->
          getr R' 18 = Z_to_bv 64 pp -> getr R' 20 = Z_to_bv 64 3 -> getr R' 21 = Z_to_bv 64 0x10000 ->
          realizes asegs (mkCfg msF' mo') T) ->
      realizes asegs (mkCfg msF mo) T.
Proof.
